import ctypes

def memory_allocation_and_copy():
    # Allocate 1024 bytes for buf
    buf = ctypes.create_string_buffer(1024)
    if not buf:
        return -1

    # Allocate 1024 bytes for buf1
    buf1 = ctypes.create_string_buffer(1024)
    if not buf1:
        return -1

    # Read up to 1024 characters from stdin
    try:
        input_data = input()[:1024]  # Read from stdin and limit to 1024 chars
    except Exception:
        return -1

    # Copy first 100 characters from input_data to buf
    if len(input_data) > 0:
        buf.raw = input_data[:100].encode('utf-8')

    # Copy first 100 characters from input_data to buf1
    if len(input_data) > 0:
        buf1.raw = input_data[:100].encode('utf-8')

    return 0
